function find_Rotations(str){
    let rotations = 0;
    let original = str;
    while (rotations < str.length) {
        str = str.slice(1) + str.charAt(0);
        rotations++;
        if (str === original) {
            return rotations;
        }
    }
    return rotations;
}

function find_kth(arr1, arr2, k){
    let i = 0, j = 0;
    while (i < arr1.length && j < arr2.length) {
        if (arr1[i] < arr2[j]) {
            k--;
            if (k === 0) return arr1[i];
            i++;
        } else {
            k--;
            if (k === 0) return arr2[j];
            j++;
        }
    }
    while (i < arr1.length) {
        k--;
        if (k === 0) return arr1[i];
        i++;
    }
    while (j < arr2.length) {
        k--;
        if (k === 0) return arr2[j];
        j++;
    }
    throw new Error("k is out of bounds");
}

function next_smallest(lst){
  if (lst.length < 2) return undefined;
  let smallest = Infinity;
  let secondSmallest = Infinity;

  for (let i = 0; i < lst.length; i++) {
    if (lst[i] < smallest) {
      secondSmallest = smallest;
      smallest = lst[i];
    } else if (lst[i] < secondSmallest && lst[i] !== smallest) {
      secondSmallest = lst[i];
    }
  }

  return secondSmallest === Infinity ? undefined : secondSmallest;
}

