function get_closest_vowel(word){
    const vowels = 'aeiouAEIOU';
    for (let i = word.length - 2; i > 0; i--) {
        const char = word[i];
        if (vowels.includes(char)) {
            for (let j = i - 1; j >= 0; j--) {
                if (!vowels.includes(word[j])) {
                    return char;
                }
            }
        }
    }
    return '';
}
